WITH kept_keys AS (SELECT product_id, id FROM store_sales INTERSECT ALL SELECT product_id, id FROM store_sales WHERE units < 19), kept_rows AS (SELECT s.* FROM store_sales s INNER JOIN kept_keys k ON s.product_id = k.product_id AND s.id = k.id) SELECT s.product_id, s.sale_date, s.units, s.revenue, (SELECT MIN(o2.quantity) FROM order_items o2 WHERE o2.product_id = s.product_id) AS min_order_item_quantity FROM kept_rows s
